const $=id=>section.querySelector('#'+id),images=Array.from(stage.querySelectorAll('img')).slice(0,COUNT);let options=preset('calm'),reactive=null,seconds=0,playing=false,last=null,raf=0;const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
